/*
 * CoAP Server — Board 1
 * Reads 8-position DIP switch and serves state via CoAP
 * Resource: /dip/switches  (GET returns {"switches":<0-255>})
 */

#include <CoapServer.h>

CoapServer server(5683);

int swPins[] = {13, 12, 14, 27, 26, 25, 33, 32};
uint8_t switchState = 0;

String handleDipSwitches(String payload) {
  // Read current DIP switch state
  switchState = 0;
  for (int i = 0; i < 8; i++) {
    if (digitalRead(swPins[i]) == HIGH) {
      switchState |= (1 << i);
    }
  }
  return "{\"switches\":" + String(switchState) + "}";
}

void setup() {
  Serial.begin(115200);
  for (int i = 0; i < 8; i++) {
    pinMode(swPins[i], INPUT_PULLUP);
  }

  server.add_resource("/dip/switches", handleDipSwitches);
  server.start();

  Serial.println("[CoAP Server] Started on port 5683");
  Serial.println("[CoAP Server] Resource: /dip/switches");
  delay(2000);
}

void loop() {
  // Refresh switch state for logging
  switchState = 0;
  for (int i = 0; i < 8; i++) {
    if (digitalRead(swPins[i]) == HIGH) {
      switchState |= (1 << i);
    }
  }
  Serial.print("[Server] DIP: 0b");
  for (int i = 7; i >= 0; i--) {
    Serial.print((switchState >> i) & 1);
  }
  Serial.println();
  delay(500);
}

