/*
 * CoAP Client — Board 2
 * Polls the CoAP server for DIP switch state
 * Mirrors switch state on 8-LED array (active-high)
 */

#include <CoapClient.h>

CoapClient client;

const int Leds[8] = {21, 19, 18, 5, 17, 16, 4, 2};

void updateLEDs(uint8_t val) {
  for (int i = 0; i < 8; i++) {
    digitalWrite(Leds[i], (val >> i) & 1);
  }
}

void setup() {
  Serial.begin(115200);
  for (int i = 0; i < 8; i++) {
    pinMode(Leds[i], OUTPUT);
    digitalWrite(Leds[i], LOW);
  }
  Serial.println("[CoAP Client] Starting...");
  delay(3000);
}

void loop() {
  CoapResponse response = client.get("/dip/switches");

  if (response.valid && response.code == COAP_CONTENT) {
    // Parse: {"switches":123}
    String json = response.payload;
    int idx = json.indexOf("switches");
    if (idx >= 0) {
      idx = json.indexOf(':', idx);
      if (idx >= 0) {
        int val = json.substring(idx + 1, json.indexOf('}', idx)).toInt();
        updateLEDs((uint8_t)val);
        Serial.print("[Client] Received switches: ");
        Serial.print(val);
        Serial.print("  0b");
        for (int i = 7; i >= 0; i--) {
          Serial.print((val >> i) & 1);
        }
        Serial.println();
      }
    }
  } else {
    Serial.println("[Client] No response from server");
  }
  delay(500);
}
